#!/usr/bin/env node
/**
 * The one source of truth for "which site does a host belong to".
 *
 * Every platform (Rust, TypeScript, Kotlin, Swift) answers that question with the Public Suffix
 * List, the same data browsers use for cookies. This script owns the data:
 *
 *   node scripts/public-suffix.mjs update   # download the list and the official test vectors
 *   node scripts/public-suffix.mjs check    # fail when a generated file is out of date (CI)
 *
 * It writes, under `shared/public-suffix/`:
 *   public_suffix_public_suffix_rules.txt (in resources/)  one rule per line: `a.b`, `*.a.b` or `!x.a.b`, in ASCII (punycode)
 *   vectors.json  `[host, registrableDomain | null]` pairs every matcher must reproduce
 * and generates `PublicSuffixRules.swift` in the iOS plugin, because a static Swift package has
 * no reliable way to ship a resource file. Rust, TypeScript and Kotlin read `public_suffix_rules.txt` itself.
 *
 * Plain one-label rules (`com`, `uk`) are dropped: the list's default rule gives the same answer.
 */
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { domainToASCII, fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const DIR = path.join(ROOT, "shared", "public-suffix");
const RULES = path.join(DIR, "resources", "public_suffix_rules.txt");
const VECTORS = path.join(DIR, "vectors.json");
const SWIFT = path.join(
  ROOT,
  "src-tauri/plugins/tauri-plugin-siteview/ios/Sources/PublicSuffixRules.swift",
);

const LIST_URL = "https://publicsuffix.org/list/public_suffix_list.dat";
const TESTS_URL = "https://raw.githubusercontent.com/publicsuffix/list/main/tests/test_psl.txt";

const ascii = (text) => domainToASCII(text) || text;

/** Rules in ASCII, sorted, without the one-label plain rules the default rule already covers. */
export function parseRules(list) {
  const rules = new Set();
  for (const raw of list.split("\n")) {
    const line = raw.trim().split(/\s/)[0];
    if (!line || line.startsWith("//")) continue;
    const prefix = line.startsWith("!") ? "!" : line.startsWith("*.") ? "*." : "";
    const rule = prefix + ascii(line.slice(prefix.length));
    if (prefix === "" && !rule.includes(".")) continue;
    rules.add(rule);
  }
  return [...rules].sort();
}

/** `checkPublicSuffix('a.b', 'b')` lines of the official tests, as ASCII pairs. */
export function parseVectors(tests) {
  const vectors = [];
  for (const line of tests.split("\n")) {
    const match = /^checkPublicSuffix\((null|'[^']*'), (null|'[^']*')\);/.exec(line.trim());
    if (!match) continue;
    const [input, expected] = [match[1], match[2]].map((value) =>
      value === "null" ? null : value.slice(1, -1),
    );
    if (input === null) continue;
    vectors.push([ascii(input), expected && ascii(expected)]);
  }
  return vectors;
}

export function swiftSource(rules) {
  return `// Generated by scripts/public-suffix.mjs from shared/public-suffix/resources/public_suffix_rules.txt. Do not edit.

enum PublicSuffixRules {
  static let text = #"""
${rules.join("\n")}
"""#
}
`;
}

const read = (file) => readFile(file, "utf8").catch(() => "");

async function update() {
  const [list, tests] = await Promise.all(
    [LIST_URL, TESTS_URL].map(async (url) => {
      const response = await fetch(url);
      if (!response.ok) throw new Error(`${url}: ${response.status}`);
      return response.text();
    }),
  );
  const rules = parseRules(list);
  await writeFile(RULES, `${rules.join("\n")}\n`);
  const vectors = parseVectors(tests);
  await writeFile(
    VECTORS,
    `[\n${vectors.map((pair) => ` ${JSON.stringify(pair)}`).join(",\n")}\n]\n`,
  );
  await writeFile(SWIFT, swiftSource(rules));
  console.log(`${rules.length} rules, ${vectors.length} vectors`);
}

async function check() {
  const rules = (await read(RULES)).split("\n").filter(Boolean);
  if ((await read(SWIFT)) !== swiftSource(rules)) {
    console.error(
      "PublicSuffixRules.swift is out of date: run `node scripts/public-suffix.mjs generate`",
    );
    process.exit(1);
  }
}

async function generate() {
  const rules = (await read(RULES)).split("\n").filter(Boolean);
  await writeFile(SWIFT, swiftSource(rules));
}

const commands = { update, check, generate };
const command = commands[process.argv[2]];
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  if (!command) {
    console.error("Usage: node scripts/public-suffix.mjs update|generate|check");
    process.exit(1);
  }
  await command();
}
